select ?lexemeId ?lemma ?example ?sourceLabel ?source
WHERE {
?lexemeId <http://purl.org/dc/terms/language> wd:Q9027;
wikibase:lemma ?lemma.
?lexemeId p:P5831 ?statement.
?statement ps:P5831 ?example;
pq:P6072 [];
pq:P5830 [].
?lexemeId p:P5831 [ prov:wasDerivedFrom [ pr:P248 ?source ] ].
SERVICE wikibase:label { bd:serviceParam wikibase:language "sv,en". }
}

generated_query:
SELECT ?lexeme ?lemma ?formExample ?senseExample ?source WHERE {
  ?lexeme dct:language wd:Q9027 ;
          wikibase:lemma ?lemma .
  ?lexeme p:P5831 ?statement .
  ?statement ps:P5831 ?example .
  ?statement pq:P5830 ?form .
  ?statement pq:P6072 ?sense .
  OPTIONAL { ?statement prov:wasDerivedFrom ?source . }
  BIND(?example AS ?formExample)
  BIND(?example AS ?senseExample)
}
